index:
import { agent } from "@b4run/sdk"

export default agent({
  model: "gpt-5-mini",
  systemPrompt: "You are a friendly assistant. Use greet to greet people by name.",
})

greet:
/** Greet someone by name. */
export default async (input: { readonly name: string }) => {
  return { message: `Hello, ${input.name}!` }
}

memory:
import { defineMemory } from "@b4run/sdk"
import { z } from "zod"

export default defineMemory({
  kind: "semantic",
  scope: ["workspace", "route"],
  schema: z.object({
    subject: z.string(),
    predicate: z.string(),
    value: z.string(),
  }),
})

subagent:
import { agent } from "@b4run/sdk"

export default agent({
  model: "gpt-5-mini",
  description: "Translate a short greeting into the language the user asks for.",
  systemPrompt: "You translate greetings. Reply with the translation only.",
})

eval:
import { contains, defineEval } from "@b4run/evals"
import { script } from "@b4run/testing"

export default defineEval({
  name: "greets by name",
  dataset: [
    {
      name: "ada",
      input: "Say hello to Ada",
      fixtures: script().user("Say hello to Ada").replies("Hello, Ada!"),
    },
  ],
  scorers: [contains("Hello", { threshold: 1 })],
  threshold: 1,
})
